export const assets={"/assets/style.css":{"body":":root{font-family:system-ui,-apple-system,\"Segoe UI\",sans-serif;color:#242d2a;background:#f5f6f2;font-size:15px}*{box-sizing:border-box}body{margin:0}button,input,select,textarea{font:inherit}button,a,input,select,textarea{touch-action:manipulation}button{cursor:pointer;border:1px solid #ccd4ce;background:white;color:#24372d;padding:10px 14px;border-radius:9px;font-weight:600}button:hover{background:#e9eee7}button:disabled{opacity:.5;cursor:wait}.primary{background:#214f3b;color:#fff;border-color:#214f3b}.primary:hover{background:#153c2b}a{color:#265b46}input,textarea,select{max-width:100%;min-width:0;border:1px solid #cbd3cb;border-radius:7px;background:#fff;padding:9px;color:#24372d}input[type=number]{width:95px}input[type=checkbox]{width:18px;height:18px;accent-color:#24533c}label{display:flex;flex-direction:column;gap:7px;font-size:14px;font-weight:600}textarea{width:100%;resize:vertical}label.check{flex-direction:row;align-items:flex-start;font-weight:400;line-height:1.6;margin:14px 0}label.check input{flex-shrink:0;margin-top:3px}.shell{max-width:1600px;margin:auto;padding:38px 40px 18px}header{display:flex;justify-content:space-between;gap:32px;margin-bottom:26px}h1{font-size:42px;letter-spacing:-1.5px;line-height:1.12;margin:6px 0 12px}h2{font-size:23px;margin:0 0 14px;letter-spacing:-.5px}h3{font-size:19px}p{line-height:1.6}.eyebrow{font-size:11px;font-weight:750;letter-spacing:1.8px;color:#53715d;margin:0}.muted,small{color:#6b746c}.muted{font-size:13px}small{display:block;font-size:11px;line-height:1.5;margin-top:5px}.header-actions{display:flex;flex-wrap:wrap;align-content:start;align-items:center;justify-content:flex-end;gap:10px;max-width:480px}.cloud{font-size:12px;color:#356145;flex-basis:100%;text-align:right}.pending{color:#a15e15}.notice{border-radius:12px;border:1px solid;padding:16px 20px;display:flex;gap:18px;align-items:baseline;font-size:14px}.notice span{font-size:13px}.amber{background:#fff5dc;border-color:#e9dcb4;color:#76551d}.green{background:#e5f1e7;border-color:#b9d9be;color:#265533}nav{display:flex;gap:7px;margin:24px 0 20px;flex-wrap:wrap}nav button{background:transparent;border-color:transparent}.active,nav button.active{background:#e1e9df;border-color:#bdcdbb;color:#204c32}.basis{display:flex;align-items:end;flex-wrap:wrap;gap:18px;border-bottom:1px solid #d9ded4;padding:0 0 18px;margin-bottom:24px}.basis>div{margin-right:auto}.basis>p{flex-basis:100%;font-size:12px;margin:0;color:#788176}.basis label{font-size:12px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:15px;margin:22px 0}.stats>div{border:1px solid #dce2d7;background:#fff;padding:20px;border-radius:12px}.stats b{font-size:31px;letter-spacing:-1px}.stats span{display:block;color:#6c766b;font-size:12px;margin-top:4px}.toolbar{display:flex;align-items:center;flex-wrap:wrap;gap:10px;margin:18px 0}.segmented{display:flex;gap:3px}.toolbar #search{flex:1;min-width:170px}.toolbar h2{margin:0 auto 0 0}.table-wrap{overflow:auto;border:1px solid #dce2d7;background:#fff;border-radius:12px;max-height:72vh}table{border-collapse:collapse;width:100%;font-size:13px}th{text-align:left;font-size:11px;font-weight:650;letter-spacing:.15px;color:#596b5d;background:#f0f3eb;position:sticky;top:0;z-index:1;padding:14px 12px;white-space:nowrap}td{padding:13px 12px;border-top:1px solid #e8ece4;vertical-align:top;line-height:1.5}td:first-child{min-width:245px;max-width:430px}tr:hover{background:#fbfcf7}.question-row{background:#fff9ed}.product{padding:0;background:none;border:0;text-align:left;line-height:1.5;font-weight:650;font-size:13px}.product:hover{text-decoration:underline;background:none}.qty{font-weight:750;font-size:21px;color:#28553a;white-space:nowrap}.reason{color:#788171;min-width:180px;max-width:300px;font-size:11px}.warn{color:#a46620!important}.panel{padding:24px;border-radius:12px;background:#fff;border:1px solid #dce2d7;margin:20px 0}.panel p{font-size:14px}.panel label{margin:16px 0}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:20px}.grid2 .panel{margin:0}.grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.grid3 label{margin:0}.grid3 input{width:100%}.upload{padding:20px;background:#eef3eb;border:1px dashed #9cac99;border-radius:10px;display:flex;flex-direction:row;align-items:center;justify-content:space-between;gap:12px}.upload input{border:none;background:none}.import{border-top:1px solid #dce2d7;margin-top:20px;padding-top:15px}.import-lines{max-height:55vh;margin-top:16px}.import-lines td:first-child{max-width:300px}.import-lines select{max-width:330px}.import-lines input[type=number]{width:75px}.rule{display:flex;justify-content:space-between;gap:24px}.rule p{margin:8px 0}.version{border-top:1px solid #e0e5da;padding:18px 0}.version p{margin:8px 0}.version button{font-size:12px}.empty{text-align:center;color:#77836f;padding:30px}.mini-stats{display:flex;gap:20px;flex-wrap:wrap}.mini-stats b{background:#eef3e9;border-radius:8px;padding:13px}details summary{cursor:pointer;font-weight:600}footer{display:flex;justify-content:space-between;gap:24px;font-size:11px;color:#788170;padding:28px 0;flex-wrap:wrap}dialog{border:1px solid #ccd4c6;border-radius:16px;box-shadow:0 24px 100px #172b2830;max-width:900px;width:90vw;padding:32px;max-height:90vh;color:#24372d}dialog::backdrop{background:#122b2466}.close{float:right;font-size:24px;border:0;padding:0 8px}#toast{display:none;position:fixed;bottom:25px;left:50%;transform:translateX(-50%);max-width:90vw;background:#243d30;color:white;padding:16px 24px;border-radius:10px;box-shadow:0 10px 40px #142a2730;z-index:10;font-size:14px}#toast.visible{display:block}button:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:3px solid #88ad75;outline-offset:3px}@media(max-width:850px){.shell{padding:24px 16px}header{display:block}h1{font-size:34px}.header-actions{max-width:none;justify-content:flex-start}.cloud{text-align:left}.notice{display:block}.notice span{display:block;margin-top:6px}.stats{grid-template-columns:repeat(2,1fr)}.grid2,.grid3{grid-template-columns:1fr}.panel{padding:18px}.toolbar{gap:8px}.basis{gap:12px}.basis>div{flex-basis:100%}.basis label{flex:1;min-width:95px}nav{gap:0}nav button{font-size:12px;padding:10px}.upload{display:block}.upload input{margin-top:10px}dialog{padding:20px;width:96vw}table td:first-child{min-width:220px}.rule{display:block}}@media print{nav,.header-actions,.basis,.toolbar,footer{display:none}.shell{padding:0}.table-wrap{max-height:none;overflow:visible}th{position:static}.panel{break-inside:avoid}body{background:white}}\n","type":"text/css;charset=utf-8"},"/assets/app.js":{"body":"import {emptyState,calculate,validateState,basisKey,dateAfter} from './engine.js';\r\nimport {parseFile,matchRows,columnName} from './parser.js';\r\nconst BASE=window.APP_BASE||'/projects/notd_v2',app=document.querySelector('#app');\r\nlet backup=null;\r\nlet data=null,state=emptyState(),revision=null,documents=[],result=null,tab='order',brand='all',filter='order',search='',dirty=false,cloud='Загружаем сохранённую встречу…',importer=null,lastVersion=null,busy=false;\r\nconst e=x=>String(x??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\r\nconst n=x=>x===null||x===undefined?'—':Number(x).toLocaleString('ru-RU',{maximumFractionDigits:1});\r\nconst bn=b=>b==='notd'?'NOTD':'Biblioteka';\r\nconst $=s=>app.querySelector(s);\r\nasync function api(path,options={}){const res=await fetch(BASE+'/api/'+path,{cache:'no-store',...options});const body=await res.json().catch(()=>({error:'Сервер не ответил. Обновите страницу и войдите снова.'}));if(!res.ok)throw Error(body.error||'Ошибка сохранения');return body;}\r\nfunction mark(){dirty=true;cloud='Есть несохранённые изменения';try{localStorage.setItem('eldar-v2-backup',JSON.stringify({state,revision,asOf:data?.meetingDate}));}catch{}render();}\r\nfunction totals(rows){return {count:rows.length,units:rows.reduce((s,r)=>s+(r.suggested||0),0)};}\r\nfunction shownRows(){return result.rows.filter(r=>(brand==='all'||r.brand===brand)&&(!search||(r.name+' '+r.sku).toLowerCase().includes(search.toLowerCase()))&&(filter==='all'||filter==='order'&&(r.suggested>0||r.quantity>0||r.unknownStock||r.conflict)||filter==='risk'&&(r.early>0||r.conflict||r.unknownStock||r.stale)||filter==='edited'&&r.hasOverride)).sort((a,b)=>(b.early||0)-(a.early||0)||(b.suggested||0)-(a.suggested||0));}\r\nfunction render(){\r\n if(!data){app.innerHTML=`<main class=\"shell\"><p class=\"eyebrow\">NOTD + BIBLIOTEKA / ЗАКУПКИ</p><h1>Готовим встречу</h1><p role=\"status\">${e(cloud)}</p><label class=\"panel\">Первичная загрузка среза CRM <input id=\"seed\" type=\"file\" accept=\".json\"></label></main>`;$('#seed')?.addEventListener('change',seed);return;}\r\n result=calculate(data,state);const rows=shownRows(),total=totals(result.rows.filter(r=>r.suggested>0&&(brand==='all'||r.brand===brand)));const missing=Object.entries(state.complete).filter(([b,c])=>!c).map(([b])=>bn(b));\r\n app.innerHTML=`<div class=\"shell\"><header><div><p class=\"eyebrow\">NOTD + BIBLIOTEKA · ВСТРЕЧА 16 ОКТЯБРЯ</p><h1>Что заказываем?</h1><p class=\"muted\">Сначала проверяем предложение. Затем добавляем закупки и поправки — и сравниваем результат.</p></div><div class=\"header-actions\"><span class=\"cloud ${dirty?'pending':''}\" role=\"status\">${e(cloud)}</span><button id=\"save\" ${busy?'disabled':''}>Сохранить встречу</button><button class=\"primary\" id=\"recalc\" ${busy?'disabled':''}>Пересчитать и сохранить версию</button></div></header>\r\n <div class=\"notice ${missing.length?'amber':'green'}\"><strong>${missing.length?'Черновик: неизвестные закупки не учтены':'Закупки учтены со слов владельца'}</strong><span>${missing.length?'Для '+e(missing.join(' и '))+': загрузите последние заказы во вкладке «Поставки». Это не означает, что товара в пути нет.':'В расчёт входят только оставшиеся количества с подтверждённой датой приезда.'}</span></div>\r\n <nav aria-label=\"Разделы встречи\">${[['order','1. Предложение'],['supply','2. Поставки'],['rules','3. Правила'],['meeting','4. Решения и версии']].map(([id,label])=>`<button data-tab=\"${id}\" class=\"${tab===id?'active':''}\">${label}</button>`).join('')}</nav>\r\n <section class=\"basis\"><div><strong>Данные CRM на ${e(data.meetingDate)}</strong><small>Продажи 18.09–15.10 · 28 дней · свободный остаток после резерва</small></div><label>Пересмотр через <select id=\"review\"><option value=\"7\" ${state.params.review===7?'selected':''}>7 дней</option><option value=\"14\" ${state.params.review===14?'selected':''}>14 дней</option></select></label><label>Доставка, дней <input id=\"lead\" type=\"number\" min=\"0\" max=\"90\" value=\"${state.params.lead}\"></label><label>Запас на задержку, дней <input id=\"buffer\" type=\"number\" min=\"0\" max=\"90\" value=\"${state.params.buffer}\"></label><p>7 / 14 / 7 — стартовые допущения, согласованные с Максом. Сроки конкретного маршрута уточняем на встрече.</p></section>\r\n ${tab==='order'?`<section class=\"stats\"><div><b>${n(total.count)}</b><span>позиций в предложении</span></div><div><b>${n(total.units)}</b><span>штук предлагает расчёт</span></div><div><b>${n(result.rows.filter(r=>r.early>0&&(brand==='all'||r.brand===brand)).length)}</b><span>рисков до приезда заказа</span></div><div><b>${n(result.summary.unknownStock)}</b><span>товаров без свежего остатка</span></div></section>\r\n <div class=\"toolbar\"><div class=\"segmented\">${[['all','Оба бренда'],['notd','NOTD'],['biblioteka','Biblioteka']].map(([id,l])=>`<button data-brand=\"${id}\" class=\"${brand===id?'active':''}\">${l}</button>`).join('')}</div><input id=\"search\" placeholder=\"Название или артикул\" aria-label=\"Поиск товара\" value=\"${e(search)}\"><select id=\"filter\" aria-label=\"Показать товары\">${[['order','Предлагаем заказать + вопросы'],['risk','Требуют внимания'],['edited','С решением владельца'],['all','Весь известный ассортимент']].map(([v,l])=>`<option value=\"${v}\" ${filter===v?'selected':''}>${l}</option>`).join('')}</select><button id=\"csv\">Скачать список CSV</button></div>\r\n <p class=\"muted\">Показано ${rows.length} из ${result.rows.filter(r=>brand==='all'||r.brand===brand).length} известных товаров. Все подходящие строки, без ограничения в пять товаров. Нажмите на товар, чтобы понять расчёт или оставить решение.</p>\r\n <div class=\"table-wrap\"><table><thead><tr><th>Товар</th><th>Продано<br>за 28 дней</th><th>Свободно<br>сейчас</th><th>В пути<br>в срок</th><th>Предлагаем<br>докупить</th><th>Решение<br>владельца</th><th>Почему / что проверить</th></tr></thead><tbody>${rows.map(r=>`<tr class=\"${r.conflict||r.unknownStock?'question-row':''}\"><td><button class=\"product\" data-product=\"${e(r.id)}\">${e(r.name)}</button><small>${bn(r.brand)} · ${e(r.sku)}</small></td><td>${n(r.sales)}</td><td>${n(r.free)}</td><td>${n(r.inbound)}${r.undated?`<small class=\"warn\">+${n(r.undated)} без даты</small>`:''}${r.later?`<small>+${n(r.later)} позже</small>`:''}</td><td class=\"qty\">${n(r.suggested)}</td><td><button data-product=\"${e(r.id)}\" class=\"${r.stale?'warn':''}\">${r.hasOverride?n(r.quantity)+(r.stale?' ↻':' ✓'):'Проверить'}</button></td><td class=\"reason\">${e(r.reason||r.warnings.find(x=>!x.startsWith('Не подтверждено'))||(r.suggested>0?'Не хватает на расчётный период':'Пока хватает'))}</td></tr>`).join('')}</tbody></table>${rows.length?'':'<p class=\"empty\">По этому фильтру товаров нет.</p>'}</div>\r\n <details class=\"panel\"><summary>Простыми словами: откуда количество?</summary><p>Берём продажи за 28 дней и делим на 28. Смотрим потребность на срок доставки + до следующего пересмотра + запас на задержки. Вычитаем свободный остаток и только те подтверждённые поставки, которые успеют приехать.</p><p>Проверяем каждый день: поздняя поставка не скрывает нехватку до её приезда. Недостаток до приезда новой закупки отмечаем отдельно — обычная доставка его вовремя не исправит.</p><p>Это проверяемая гипотеза, а не подтверждённый владельцем прогноз. Нулевые продажи при отсутствии товара не доказывают отсутствие спроса. Не добавляем автоматически +30%, скидку, минимальную партию или округление до пяти.</p></details>`:tab==='supply'?supplyView():tab==='rules'?rulesView():meetingView()}\r\n <footer><span>CRM остаётся источником фактов. Здесь — расчёт и решения; CRM не меняется.</span><a href=\"https://drive.google.com/drive/folders/1HgKpmme8smoLsZhRRUnQu-FADarOnL2F\" target=\"_blank\" rel=\"noreferrer\">Папка документов Drive ↗</a><a href=\"${BASE}/logout\">Выйти</a></footer></div><dialog id=\"detail\"></dialog><div id=\"toast\" role=\"alert\"></div>`;\r\n bind();\r\n}\r\nfunction supplyView(){return `<section class=\"panel\"><h2>Загрузите последние заказы целиком</h2><p>Не нужно перечислять сто артикулов. Прикрепите XLSX, CSV или текстовый PDF, выберите колонку количества и проверьте найденные позиции.</p><label class=\"upload\">Выбрать файл заказа <input id=\"upload\" type=\"file\" accept=\".xlsx,.csv,.pdf\"></label><p class=\"muted\">До 3,5 МБ. Оригиналы сохраняются в закрытом хранилище сайта. Автоматическое копирование в Drive пока не подключено; папка доступна по ссылке внизу.</p>${importer?importView():''}</section>\r\n <section class=\"grid2\">${['notd','biblioteka'].map(b=>`<div class=\"panel\"><h2>${bn(b)}</h2><label class=\"check\"><input type=\"checkbox\" data-complete=\"${b}\" ${state.complete[b]?'checked':''}> Все ещё не полученные закупки на дату среза учтены (либо их нет)</label><p class=\"muted\">Уже полученное не добавляем в путь: оно включено в свежий остаток CRM. Поставки после даты среза требуют обновления остатка.</p></div>`).join('')}</section>\r\n ${(state.orders||[]).map((p,i)=>`<section class=\"panel\"><div class=\"toolbar\"><h2>${e(p.number)} · ${bn(p.brand)}</h2><span>${p.lines.length} товаров · осталось ${n(p.lines.reduce((s,l)=>s+l.ordered-l.received-l.cancelled,0))} шт.</span><button data-po=\"${i}\">Проверить получение и дату</button></div><p>${p.confirmed?'Подтверждённая закупка':'Не подтверждена'} · приезжает ${e(p.eta||'дата неизвестна')} · ${e(p.filename||'')}</p><small>Форма заказа и счёт на ту же закупку — один номер закупки. Новая версия заменяет строки, а не суммирует их.</small></section>`).join('')||'<p class=\"empty\">Заказы ещё не добавлены. Предложение пока без неизвестного товара в пути.</p>'}\r\n <section class=\"panel\"><h2>Сохранённые оригиналы</h2>${documents.map(d=>`<p><a href=\"${BASE}/api/document/${e(d.id)}\">${e(d.filename)}</a> <small>${e(d.createdAt?.slice(0,16))}</small></p>`).join('')||'<p>Пока нет документов.</p>'}</section>`;}\r\nfunction importView(){const it=importer;return `<div class=\"import\"><h3>${e(it.filename)}</h3>${it.error?`<p class=\"warn\">${e(it.error)}</p>`:''}${it.sheets?`<div class=\"toolbar\"><label>Лист <select id=\"sheet\">${it.sheets.map((s,i)=>`<option value=\"${i}\" ${i===it.sheet?'selected':''}>${e(s.name)}</option>`).join('')}</select></label><label>Бренд <select id=\"import-brand\"><option value=\"notd\" ${it.brand==='notd'?'selected':''}>NOTD</option><option value=\"biblioteka\" ${it.brand==='biblioteka'?'selected':''}>Biblioteka</option></select></label><label>Заголовок до строки <input id=\"header-row\" type=\"number\" min=\"0\" value=\"${it.header}\"></label><label>Количество в колонке <select id=\"qty-col\"><option value=\"\">Выберите явно</option>${Array.from({length:Math.max(...it.sheets[it.sheet].rows.map(r=>r.cells.length),1)},(_,i)=>`<option value=\"${i}\" ${it.qtyColumn===i?'selected':''}>${columnName(i)} · ${e(it.sheets[it.sheet].rows.filter(r=>r.number<=Math.max(it.header,8)).map(r=>r.cells[i]).filter(Boolean).join(' / ').slice(-90))}</option>`).join('')}</select></label><button id=\"parse-lines\">Проверить позиции</button></div><details><summary>Показать первые строки файла</summary><div class=\"table-wrap\"><table><tbody>${it.sheets[it.sheet].rows.slice(0,18).map(r=>`<tr><th>${r.number}</th>${Array.from({length:Math.min(r.cells.length,28)},(_,i)=>`<td><small>${columnName(i)}</small>${e(r.cells[i])}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details>`:''}\r\n ${it.lines?`<p><strong>${it.lines.length} строк с положительным количеством</strong> · не распознано/спорно: ${it.lines.filter(l=>!l.id||l.invalid).length}. Проверьте: выбрана именно колонка «шт.», например EUR шт., а не цена.</p><div class=\"toolbar\"><label>Номер закупки <input id=\"po-number\" value=\"${e(it.number)}\" placeholder=\"Номер счёта или дата + склад\"></label><label>Ожидаем в Испании <input id=\"po-eta\" type=\"date\" value=\"${e(it.eta||'')}\"></label></div><label class=\"check\"><input id=\"po-confirm\" type=\"checkbox\" ${it.confirmed?'checked':''}> Это реальная закупка. Колонка количества верна; полученные количества проверены на дату среза.</label><div class=\"table-wrap import-lines\"><table><thead><tr><th>Строка файла</th><th>Товар CRM / артикул</th><th>Заказано</th><th>Уже получено</th><th>Не учитывать / причина</th></tr></thead><tbody>${it.lines.map((l,i)=>`<tr><td><small>${e(l.label)}</small>${l.page?'стр. PDF '+l.page+' · ':''}строка ${l.row}</td><td>${l.id&&!l.remap?`<strong>${e(data.rows.find(r=>r.id===l.id)?.name)}</strong><small>${e(data.rows.find(r=>r.id===l.id)?.sku)}</small><button data-remap=\"${i}\">Изменить совпадение</button>`:`<select data-map=\"${i}\"><option value=\"\">Выберите совпадение</option>${data.rows.filter(r=>r.brand===it.brand).map(r=>`<option value=\"${e(r.id)}\" ${l.id===r.id?'selected':''}>${e(r.sku+' · '+r.name)}</option>`).join('')}</select>`}</td><td><input type=\"number\" min=\"0\" step=\"1\" value=\"${l.qty}\" data-import-qty=\"${i}\"></td><td><input type=\"number\" min=\"0\" step=\"1\" value=\"${l.received||0}\" data-received=\"${i}\"></td><td><label><input type=\"checkbox\" data-exclude=\"${i}\" ${l.excluded?'checked':''}> Пропустить</label><input placeholder=\"Причина пропуска\" value=\"${e(l.reason)}\" data-exclude-reason=\"${i}\"></td></tr>`).join('')}</tbody></table></div><label class=\"check\"><input id=\"separate-po\" type=\"checkbox\"> Если похожие позиции есть в других заказах: подтверждаю, что это отдельная партия</label><button class=\"primary\" id=\"apply-import\">Учесть закупку и пересчитать</button><p class=\"muted\">Совпавший номер обновит существующую закупку. Нераспознанную строку нужно сопоставить или явно исключить с причиной.</p>`:''}</div>`;}\r\nfunction scopeOptions(){return `<option value=\"all\">Оба бренда</option><option value=\"notd\">NOTD</option><option value=\"biblioteka\">Biblioteka</option>${[...new Set(data.rows.map(r=>'category:'+r.brand+':'+r.category))].map(s=>`<option value=\"${e(s)}\">${bn(s.split(':')[1])}: ${e(s.split(':').slice(2).join(':'))}</option>`).join('')}${data.rows.map(r=>`<option value=\"${e(r.id)}\">${e(r.sku+' · '+r.name)}</option>`).join('')}`;}\r\nfunction rulesView(){return `<section class=\"panel\"><h2>База отдельно. Обстоятельства отдельно.</h2><p>Сезон и акция меняют спрос. Проблемы поставщика меняют срок доставки. Разовый B2B-заказ добавляется только сверх обычного спроса и только если ещё не попал в резерв CRM.</p><form id=\"rule-form\"><div class=\"grid3\"><label>Что меняем <select name=\"kind\"><option value=\"demand\">Спрос × коэффициент</option><option value=\"delivery\">Доставка: новое число дней</option><option value=\"extra\">Разовый дополнительный заказ, шт.</option></select></label><label>Для кого <select name=\"scope\">${scopeOptions()}</select></label><label>Значение <input name=\"value\" type=\"number\" min=\"0\" step=\"0.01\" value=\"1.3\" required></label><label>С даты <input name=\"from\" type=\"date\" value=\"${e(data.meetingDate)}\" required></label><label>До даты <input name=\"to\" type=\"date\" value=\"${dateAfter(data.meetingDate,28)}\" required></label><label>Приоритет при одинаковой точности <input name=\"priority\" type=\"number\" value=\"0\" min=\"0\" max=\"100\"></label></div><label>Причина / откуда знаем <input name=\"reason\" placeholder=\"Например: выставка, согласовано с Эльдаром, +30% для этих товаров\" required></label><label class=\"check\"><input name=\"incremental\" type=\"checkbox\"> Для разового заказа: он сверх обычных продаж и ещё не зарезервирован в CRM</label><button class=\"primary\">Добавить правило и пересчитать</button></form></section>\r\n ${(state.rules||[]).map((r,i)=>`<section class=\"panel rule\"><div><strong>${r.kind==='demand'?'Спрос ×'+r.value:r.kind==='delivery'?'Доставка '+r.value+' дней':'Разовый спрос +'+r.value+' шт.'}</strong><p>${e(scopeLabel(r.scope))} · ${e(r.from||'без начала')} → ${e(r.to||'без конца')} · приоритет ${r.priority||0}</p><p>${e(r.reason)}</p></div><label><input type=\"checkbox\" data-rule-enabled=\"${i}\" ${r.enabled!==false?'checked':''}> Применять</label></section>`).join('')||'<p class=\"empty\">Поправок нет. Никакое увеличение «на сезон» не включено автоматически.</p>'}\r\n <details class=\"panel\"><summary>Если правила противоречат друг другу</summary><p>Правило для конкретного товара важнее правила категории, затем бренда, затем общего. При одинаковой точности побеждает больший приоритет. Если приоритеты равны, а значения разные — показываем конфликт; количество для затронутого товара не выдаём, пока не выбрано правило.</p><p>Два множителя не перемножаются автоматически. Разовые B2B-заказы суммируются по своим датам; сезонный множитель их не увеличивает. Для изменений маршрута задайте правило доставки конкретному бренду или товару.</p></details>`;}\r\nfunction scopeLabel(s){if(s==='all')return'Оба бренда';if(['notd','biblioteka'].includes(s))return bn(s);return data.rows.find(r=>r.id===s)?.name||s.replace('category:','Категория ');}\r\nconst QUESTIONS=[['statuses','Какие статусы заказов означают реальную продажу? Что делать с отменами и возвратами?'],['shortage','Какие товары отсутствовали на складе и поэтому продались меньше обычного?'],['routes','Какие сроки по Украине и Польше считать обычными и какие задержки уже известны?'],['events','Какие акции, выставки и сезонные изменения впереди? Для каких товаров и на какие даты?'],['constraints','Есть ли лимит бюджета, минимальная партия или ограничения на перевозку?']];\r\nfunction meetingView(){const versions=state.versions||[];return `<section class=\"panel\"><h2>Пять вопросов для встречи</h2><p>Ответы сохраняем здесь. Численные изменения внесите во вкладке «Правила» или в карточке товара: один текстовый комментарий сам по себе формулу не меняет.</p>${QUESTIONS.map(([k,q])=>`<label>${q}<textarea data-note=\"${k}\" rows=\"2\" placeholder=\"Короткий ответ / что нужно проверить\">${e(state.notes[k]||'')}</textarea></label>`).join('')}</section><section class=\"panel\"><h2>Сохранённые версии</h2><p>Кнопка «Пересчитать» сохраняет входные данные, правила и результаты. Ручные решения после изменения базы нужно подтвердить снова.</p>${versions.slice().reverse().map(v=>`<div class=\"version\"><strong>${e(v.label||v.id)}</strong> · ${e(v.createdAt?.slice(0,16))}<p>${v.count} позиций · ${n(v.units)} шт. · ${v.changed} позиций изменилось ${v.previous?'относительно предыдущей версии':'относительно базы без поставок и правил'}</p><button data-version=\"${e(v.id)}\">Посмотреть изменения</button></div>`).join('')||'<p>Версий пока нет. Проверьте предложение и сохраните первую.</p>'}${lastVersion?.comparison?`<h3>${e(lastVersion.label)}: что изменилось</h3><p>Сравниваем с ${lastVersion.previous?'предыдущей сохранённой версией':'базой без поставок и поправок'}.</p><div class=\"table-wrap\"><table><thead><tr><th>Товар</th><th>Было</th><th>Стало</th><th>Решение / что проверить</th></tr></thead><tbody>${lastVersion.comparison.map(r=>`<tr><td>${e(r.name)}</td><td>${n(r.before)}</td><td class=\"qty\">${n(r.after)}</td><td>${e(r.reason||r.warnings.join('; ')||'Изменились учтённые поставки / правила')}</td></tr>`).join('')}</tbody></table></div>`:''}<button id=\"export-meeting\">Скачать всю встречу</button>${backup?'<button id=\"download-backup\">Скачать несохранённый черновик этого устройства</button>':''}</section><section class=\"panel\"><h2>Что считаем результатом встречи</h2><p>Прошли весь список, учли последние закупки, проверили сроки и поправки. На спорных товарах есть решение и причина. Затем проверяем расчёт на реальном заказе; после этого переносим тот же порядок действий в Telegram.</p><p class=\"muted\">Файл CSV — рабочий список для проверки. Это ещё не заполненная форма поставщика и не отправленный заказ.</p></section>`;}\r\nfunction bind(){\r\n for(const el of app.querySelectorAll('[data-tab]'))el.onclick=()=>{tab=el.dataset.tab;render();};\r\n for(const el of app.querySelectorAll('[data-brand]'))el.onclick=()=>{brand=el.dataset.brand;render();};\r\n for(const k of ['review','lead','buffer'])$('#'+k).onchange=ev=>{const value=Number(ev.target.value);if(!Number.isInteger(value)||value<0||value>90)return toast('Проверьте число дней');state.params[k]=value;mark();};\r\n $('#save').onclick=()=>save(false);$('#recalc').onclick=()=>save(true);\r\n $('#search')?.addEventListener('input',ev=>{const pos=ev.target.selectionStart;search=ev.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);});\r\n $('#filter')?.addEventListener('change',ev=>{filter=ev.target.value;render();});\r\n for(const el of app.querySelectorAll('[data-product]'))el.onclick=()=>detail(el.dataset.product);\r\n $('#csv')?.addEventListener('click',exportCSV);$('#upload')?.addEventListener('change',upload);\r\n for(const el of app.querySelectorAll('[data-complete]'))el.onchange=()=>{state.complete[el.dataset.complete]=el.checked;mark();};\r\n for(const el of app.querySelectorAll('[data-note]'))el.onchange=()=>{state.notes[el.dataset.note]=el.value;mark();};\r\n for(const el of app.querySelectorAll('[data-rule-enabled]'))el.onchange=()=>{state.rules[Number(el.dataset.ruleEnabled)].enabled=el.checked;mark();};\r\n $('#rule-form')?.addEventListener('submit',ev=>{ev.preventDefault();const f=new FormData(ev.target),r={id:crypto.randomUUID(),kind:f.get('kind'),scope:f.get('scope'),value:Number(f.get('value')),from:f.get('from'),to:f.get('to'),priority:Number(f.get('priority')),reason:f.get('reason'),incremental:f.get('incremental')==='on',enabled:true};const candidate=structuredClone(state);candidate.rules.push(r);try{validateState(candidate,data);state=candidate;mark();toast('Правило применено. Список пересчитан; сохраните версию.');}catch(err){toast(err.message);}});\r\n for(const el of app.querySelectorAll('[data-po]'))el.onclick=()=>poDetail(Number(el.dataset.po));\r\n for(const el of app.querySelectorAll('[data-version]'))el.onclick=async()=>{try{const v=await api('version/'+el.dataset.version);lastVersion=v;render();}catch(err){toast(err.message);}};\r\n $('#download-backup')?.addEventListener('click',()=>download('Несохранённый_черновик.json',JSON.stringify(backup,null,2),'application/json'));\r\n $('#export-meeting')?.addEventListener('click',()=>download('Закупки_встреча_'+data.meetingDate+'.json',JSON.stringify({datasetDate:data.meetingDate,state,result,documents},null,2),'application/json'));\r\n bindImport();\r\n}\r\nfunction detail(id){const r=result.rows.find(x=>x.id===id),source=data.rows.find(x=>x.id===id),ed=state.edits[id]||{};const d=$('#detail');d.innerHTML=`<form method=\"dialog\"><button class=\"close\" aria-label=\"Закрыть\">×</button></form><h2>${e(r.name)}</h2><p>${bn(r.brand)} · ${e(r.sku)}</p><div class=\"mini-stats\"><b>Продано: ${n(r.sales)}</b><b>Свободно: ${n(r.free)}</b><b>Докупить: ${n(r.suggested)}</b></div><p>${n(r.sales)} / 28 = <strong>${n(r.rate)} шт. в день</strong>. Доставка ${r.lead} + пересмотр ${state.params.review} + запас ${state.params.buffer} = <strong>${r.horizon} дней</strong>, до ${dateAfter(data.meetingDate,r.horizon)}. Ожидаемый спрос за период: ${n(r.demand)} шт.</p><p>Поставки в срок: ${n(r.inbound)}; без актуальной даты: ${n(r.undated)}; позже периода: ${n(r.later)}. Резерв CRM ${n(r.reserved)} уже вычтен из свободного остатка.</p>${r.warnings.map(w=>`<p class=\"warn\">${e(w)}</p>`).join('')}<form id=\"edit-form\"><label>Моё количество (0 = не заказывать)<input name=\"qty\" type=\"number\" min=\"0\" step=\"1\" value=\"${e(ed.qty??r.suggested??'')}\"></label><label>Почему / что проверили<textarea name=\"reason\" rows=\"3\" required>${e(ed.reason||'')}</textarea></label><label>Из 28 дней исключить разовую продажу, шт.<input name=\"excludeSales\" type=\"number\" min=\"0\" max=\"${r.sales}\" value=\"${ed.excludeSales||0}\"></label><small>Только подтверждённый разовый заказ. При нехватке товара не выдумываем недополученные продажи.</small><div class=\"toolbar\"><button class=\"primary\">Сохранить решение владельца</button><button type=\"button\" id=\"clear-edit\">Вернуться к расчёту</button></div></form><details><summary>Источник и сопоставление</summary><p>${e(source.fullName)} · EAN ${e(source.ean||'не указан')} · остаток ${e(source.sourceDate)} · ${e(source.mappingNote||'')}</p><p>Нет свежего остатка — не считаем его нулём. Совпадение продукта не означает, что поставщик гарантирует наличие.</p></details>`;d.showModal();$('#edit-form').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.target),candidate=structuredClone(state),qty=f.get('qty');candidate.edits[id]={qty:qty===''?null:Number(qty),reason:f.get('reason'),excludeSales:Number(f.get('excludeSales'))};try{validateState(candidate,data);candidate.edits[id].basis=basisKey(candidate);state=candidate;d.close();mark();}catch(err){toast(err.message);}};$('#clear-edit').onclick=()=>{delete state.edits[id];d.close();mark();};}\r\nfunction poDetail(i){const p=state.orders[i],d=$('#detail');d.innerHTML=`<form method=\"dialog\"><button class=\"close\" aria-label=\"Закрыть\">×</button></form><h2>${e(p.number)} · ${bn(p.brand)}</h2><form id=\"po-edit\"><label>Актуальная дата приезда<input name=\"eta\" type=\"date\" value=\"${e(p.eta||'')}\"></label><label class=\"check\"><input name=\"confirmed\" type=\"checkbox\" ${p.confirmed?'checked':''}> Закупка подтверждена</label><p>Укажите, сколько уже включено в остаток CRM на ${e(data.meetingDate)}. Позднее получение требует нового среза CRM.</p><div class=\"table-wrap\"><table><thead><tr><th>Товар</th><th>Заказано</th><th>Получено</th><th>Отменено</th></tr></thead><tbody>${p.lines.map((l,j)=>`<tr><td>${e(data.rows.find(r=>r.id===l.id)?.name)}</td><td>${l.ordered}</td><td><input type=\"number\" name=\"received-${j}\" min=\"0\" value=\"${l.received}\"></td><td><input type=\"number\" name=\"cancelled-${j}\" min=\"0\" value=\"${l.cancelled}\"></td></tr>`).join('')}</tbody></table></div><button class=\"primary\">Обновить закупку и пересчитать</button></form>`;d.showModal();$('#po-edit').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.target),candidate=structuredClone(state),p2=candidate.orders[i];p2.eta=f.get('eta');p2.confirmed=f.get('confirmed')==='on';p2.lines.forEach((l,j)=>{l.received=Number(f.get('received-'+j));l.cancelled=Number(f.get('cancelled-'+j));});try{validateState(candidate,data);state=candidate;d.close();mark();}catch(err){toast(err.message);}};}\r\nasync function upload(ev){const file=ev.target.files[0];if(!file)return;busy=true;cloud='Сохраняем оригинал…';render();try{const form=new FormData();form.set('file',file);const doc=await api('upload',{method:'POST',body:form});documents=await api('documents');importer={filename:file.name,documentId:doc.id,brand:brand==='biblioteka'?'biblioteka':'notd',sheet:0,header:1,qtyColumn:null,number:file.name.replace(/\\.[^.]+$/,''),eta:'',confirmed:false};try{importer.sheets=await parseFile(file);}catch(err){importer.error=err.message;}cloud='Оригинал сохранён на сервере';tab='supply';}catch(err){cloud='Не сохранено: '+err.message;toast(err.message);}finally{busy=false;render();}}\r\nfunction bindImport(){if(!importer)return;const it=importer;$('#sheet')?.addEventListener('change',ev=>{it.sheet=Number(ev.target.value);it.lines=null;it.qtyColumn=null;render();});$('#import-brand')?.addEventListener('change',ev=>{it.brand=ev.target.value;it.lines=null;render();});$('#header-row')?.addEventListener('change',ev=>{it.header=Number(ev.target.value);it.lines=null;});$('#qty-col')?.addEventListener('change',ev=>{it.qtyColumn=ev.target.value===''?null:Number(ev.target.value);it.lines=null;});$('#parse-lines')?.addEventListener('click',()=>{if(it.qtyColumn===null)return toast('Выберите колонку количества в штуках');it.lines=matchRows(it.sheets[it.sheet],it.qtyColumn,it.header,it.brand,data);render();});\r\n for(const el of app.querySelectorAll('[data-remap]'))el.onclick=()=>{it.lines[el.dataset.remap].remap=true;render();};\r\n for(const el of app.querySelectorAll('[data-map]'))el.onchange=()=>{it.lines[el.dataset.map].id=el.value||null;};\r\n for(const el of app.querySelectorAll('[data-import-qty]'))el.onchange=()=>{it.lines[el.dataset.importQty].qty=Number(el.value);};\r\n for(const el of app.querySelectorAll('[data-received]'))el.onchange=()=>{it.lines[el.dataset.received].received=Number(el.value);};\r\n for(const el of app.querySelectorAll('[data-exclude]'))el.onchange=()=>{it.lines[el.dataset.exclude].excluded=el.checked;};\r\n for(const el of app.querySelectorAll('[data-exclude-reason]'))el.onchange=()=>{it.lines[el.dataset.excludeReason].reason=el.value;};\r\n $('#po-number')?.addEventListener('change',ev=>it.number=ev.target.value.trim());$('#po-eta')?.addEventListener('change',ev=>it.eta=ev.target.value);$('#po-confirm')?.addEventListener('change',ev=>it.confirmed=ev.target.checked);\r\n $('#apply-import')?.addEventListener('click',()=>{try{if(!it.confirmed)throw Error('Подтвердите, что это закупка и колонка количества проверена');if(!it.lines?.length)throw Error('Положительных количеств нет');if(it.lines.some(l=>l.excluded&&!l.reason?.trim()))throw Error('Укажите причину для каждой пропущенной строки');const included=it.lines.filter(l=>!l.excluded);if(included.some(l=>!l.id||!Number.isInteger(l.qty)||l.qty<=0))throw Error('Сопоставьте все включённые строки и проверьте целые количества');const lines=new Map();for(const l of included){const a=lines.get(l.id)||{id:l.id,ordered:0,received:0,cancelled:0,sourceRows:[]};a.ordered+=l.qty;a.received+=l.received||0;a.sourceRows.push({sheet:it.sheets[it.sheet].name,row:l.row,page:l.page,quantityColumn:columnName(it.qtyColumn)});lines.set(l.id,a);}const po={number:it.number,brand:it.brand,eta:it.eta,confirmed:it.confirmed,filename:it.filename,documentId:it.documentId,lines:[...lines.values()],excluded:it.lines.filter(l=>l.excluded).map(l=>({row:l.row,label:l.label,reason:l.reason})),updatedAt:new Date().toISOString()};const candidate=structuredClone(state),idx=candidate.orders.findIndex(p=>p.brand===po.brand&&p.number===po.number);if(candidate.orders.some(p=>p.documentId===po.documentId&&p.number!==po.number))throw Error('Этот файл уже связан с другим номером закупки');const overlaps=candidate.orders.filter((p,j)=>j!==idx&&p.brand===po.brand&&p.lines.filter(l=>lines.has(l.id)).length>=Math.min(3,po.lines.length));if(overlaps.length&&!$('#separate-po').checked)throw Error('Похожие товары уже в закупке '+overlaps[0].number+'. Если это отдельная партия, подтвердите галочкой.');if(idx>=0)candidate.orders[idx]=po;else candidate.orders.push(po);validateState(candidate,data);state=candidate;importer=null;mark();toast('Закупка учтена. Количества пересчитаны. Сохраните версию.');}catch(err){toast(err.message);}});\r\n}\r\nasync function save(version){if(busy)return;busy=true;cloud='Сохраняем на сервере…';render();try{validateState(state,data);const res=await api(version?'recalculate':'state',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({expectedRevision:revision,state})});state=res.state;revision=res.revision;dirty=false;cloud='Сохранено '+new Date().toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'});if(res.version){lastVersion=await api('version/'+res.version.id);tab='meeting';}try{localStorage.removeItem('eldar-v2-backup');}catch{}toast(version?`Версия сохранена. Изменилось позиций: ${res.version.changed}`:'Встреча сохранена — доступна на другом устройстве');}catch(err){cloud='Не сохранено: '+err.message;toast(err.message);}finally{busy=false;render();}}\r\nfunction download(name,text,type){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}\r\nfunction exportCSV(){const lines=[['Бренд','Артикул','Товар','Продано 28 дней','Свободно','В пути в срок','Без даты','Предлагаем','Решение владельца','Нужно подтвердить заново','Причина / предупреждения'],...result.rows.filter(r=>brand==='all'||r.brand===brand).map(r=>[bn(r.brand),r.sku,r.name,r.sales,r.free,r.inbound,r.undated,r.suggested,r.hasOverride?r.quantity:'',r.stale?'Да':'',r.reason||r.warnings.join('; ')])];download('Закупки_проверка_'+data.meetingDate+'.csv','\\ufeff'+lines.map(l=>l.map(x=>'\"'+String(x??'').replace(/\"/g,'\"\"').replace(/^[=+@]/,\"'$&\")+'\"').join(';')).join('\\r\\n'),'text/csv;charset=utf-8');}\r\nfunction toast(msg){const el=$('#toast');if(!el)return;el.textContent=msg;el.classList.add('visible');setTimeout(()=>el.classList.remove('visible'),6500);}\r\nasync function seed(ev){try{const file=ev.target.files[0],payload=JSON.parse(await file.text());await api('dataset',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});await load();}catch(err){cloud=err.message;render();}}\r\nasync function load(){try{const init=await api('state');data=init.data;state=init.state||emptyState();revision=init.revision;documents=init.documents||[];cloud=data?'Все сохранённые данные загружены':'Срез CRM ещё не загружен';render();const local=JSON.parse(localStorage.getItem('eldar-v2-backup')||'null');if(local?.asOf===data?.meetingDate){backup=local;render();toast('Есть несохранённый черновик на этом устройстве. Его можно скачать во вкладке «Решения и версии».');}}catch(err){cloud=err.message;render();}}\r\nwindow.addEventListener('beforeunload',ev=>{if(dirty){ev.preventDefault();ev.returnValue='';}});\r\nawait load();\r\n","type":"text/javascript;charset=utf-8"},"/assets/engine.js":{"body":"// Deterministic meeting model. No language model, network or CRM writes.\nconst DAY = 86400000;\nexport const DEFAULT_PARAMS = Object.freeze({review:7,lead:14,buffer:7});\nexport function emptyState(){return {params:{...DEFAULT_PARAMS},rules:[],orders:[],edits:{},complete:{notd:false,biblioteka:false},notes:{},versions:[]};}\nexport function dayNumber(s){return Date.parse(s+'T00:00:00Z')/DAY;}\nexport function dateAfter(s,n){return new Date((dayNumber(s)+n)*DAY).toISOString().slice(0,10);}\nexport function canonical(x){if(Array.isArray(x))return '['+x.map(canonical).join(',')+']';if(x&&typeof x==='object')return '{'+Object.keys(x).sort().map(k=>JSON.stringify(k)+':'+canonical(x[k])).join(',')+'}';return JSON.stringify(x);}\nexport function basisKey(state){const s=canonical({params:state.params,rules:state.rules,orders:state.orders,complete:state.complete,history:Object.fromEntries(Object.entries(state.edits||{}).filter(([,v])=>v.excludeSales>0).map(([k,v])=>[k,v.excludeSales]))});let a=2166136261,b=5381;for(let i=0;i<s.length;i++){a=Math.imul(a^s.charCodeAt(i),16777619);b=Math.imul(b,33)^s.charCodeAt(i);}return (a>>>0).toString(16).padStart(8,'0')+(b>>>0).toString(16).padStart(8,'0');}\nfunction relevant(rule,row,date){return rule.enabled!==false&&(!rule.from||rule.from<=date)&&(!rule.to||rule.to>=date)&&(rule.scope==='all'||rule.scope===row.brand||rule.scope===row.id||rule.scope==='category:'+row.brand+':'+row.category);}\nfunction rank(rule){return (rule.scope?.includes(':')?(rule.scope.startsWith('category:')?2:3):rule.scope==='all'?0:1);}\nfunction pick(rules,kind,row,date,fallback){const r=rules.filter(x=>x.kind===kind&&relevant(x,row,date)).sort((a,b)=>rank(b)-rank(a)||(b.priority||0)-(a.priority||0));if(!r.length)return {value:fallback,used:[],conflict:false};const winners=r.filter(x=>rank(x)===rank(r[0])&&(x.priority||0)===(r[0].priority||0));return {value:Number(r[0].value),used:winners.map(x=>x.id),conflict:new Set(winners.map(x=>Number(x.value))).size>1};}\nexport function calculate(data,state){\n const params={...DEFAULT_PARAMS,...state.params},rules=state.rules||[],key=basisKey(state),asOf=data.meetingDate;\n if(![params.review,params.lead,params.buffer].every(x=>Number.isInteger(x)&&x>=0&&x<=90)||params.review<1)throw Error('Проверьте сроки: пересмотр 1–90, доставка и запас 0–90 дней.');\n const results=data.rows.map(row=>{\n  const edit=state.edits?.[row.id]||{},leadRule=pick(rules,'delivery',row,asOf,params.lead),lead=Math.ceil(leadRule.value),horizon=lead+params.review+params.buffer;\n  const exclusion=Number(edit.excludeSales||0),sales=Number(row.sales28??row.recentSales28??0),rate=Math.max(0,sales-exclusion)/28;\n  const unknownStock=!row.fresh||!Number.isFinite(row.available),free=unknownStock?null:row.available;\n  const arrivals=[],unknownArrivals=[],warnings=[],usedRules=new Set(leadRule.used);let conflict=leadRule.conflict;\n  for(const po of state.orders||[]){if(po.status==='cancelled')continue;for(const l of po.lines||[]){if(l.id!==row.id)continue;const remaining=Math.max(0,l.ordered-l.received-l.cancelled);if(!remaining)continue;const etaDays=dayNumber(po.eta)-dayNumber(asOf);if(po.confirmed&&po.eta&&Number.isFinite(etaDays)&&etaDays>=0){arrivals.push({day:etaDays,qty:remaining,po:po.number});}else unknownArrivals.push({qty:remaining,po:po.number});}}\n  if(unknownStock)warnings.push('Нет свежего остатка — количество не рассчитано');\n  if(!state.complete?.[row.brand])warnings.push('Не подтверждено, что учтены все закупки');\n  if(unknownArrivals.length)warnings.push('Есть заказ без подтверждённой актуальной даты приезда');\n  if(exclusion<0||exclusion>sales){warnings.push('Исключение из продаж больше продаж или отрицательное');conflict=true;}\n  let cumulative=0,peak=0,early=0,covered=0,demand=0;\n  for(let t=0;t<=horizon;t++){\n   const date=dateAfter(asOf,t),d=pick(rules,'demand',row,date,1);conflict ||= d.conflict;d.used.forEach(x=>usedRules.add(x));\n   // Forecast day 1 starts at the end of the snapshot date. Day 0 may contain dated commitments/arrivals.\n   const extra=rules.filter(x=>x.kind==='extra'&&x.incremental===true&&relevant(x,row,date)&&x.from===date).reduce((s,x)=>{usedRules.add(x.id);return s+Number(x.value);},0);\n   cumulative+=(t>0?rate*d.value:0)+extra;covered=arrivals.filter(x=>x.day<=t).reduce((s,x)=>s+x.qty,0);\n   const shortage=cumulative-(free??0)-covered;\n   if(t<lead)early=Math.max(early,shortage);else peak=Math.max(peak,shortage);\n  }\n  demand=cumulative;\n  if(conflict)warnings.push('Конфликт правил — нужно выбрать одно правило или изменить приоритет');\n  const suggested=unknownStock||conflict?null:Math.max(0,Math.ceil(peak-1e-8));\n  const inbound=arrivals.filter(x=>x.day<=horizon).reduce((s,x)=>s+x.qty,0),later=arrivals.filter(x=>x.day>horizon).reduce((s,x)=>s+x.qty,0),undated=unknownArrivals.reduce((s,x)=>s+x.qty,0);\n  if(early>0&&!unknownStock)warnings.push('Риск нехватки до приезда новой закупки: '+Math.ceil(early)+' шт.');\n  const hasOverride=edit.qty!==undefined&&edit.qty!==null&&edit.qty!=='';\n  const stale=hasOverride&&edit.basis!==key;\n  if(stale)warnings.push('После пересчёта ручное решение нужно подтвердить заново');\n  const quantity=hasOverride?Number(edit.qty):suggested;\n  const accepted=hasOverride&&!stale&&!!edit.reason?.trim();\n  return {id:row.id,brand:row.brand,sku:row.sku,name:row.name,fullName:row.fullName,category:row.category,sales,rate,free,reserved:row.reserved,suggested,quantity,hasOverride,accepted,stale,reason:edit.reason||'',inbound,later,undated,lead,horizon,demand,early:unknownStock?null:Math.max(0,Math.ceil(early-1e-8)),conflict,unknownStock,warnings,usedRules:[...usedRules],readyForSupplier:false};\n });\n return {asOf,basis:key,params,rows:results,summary:{candidates:results.filter(x=>x.suggested>0).length,units:results.reduce((s,x)=>s+(x.suggested||0),0),unknownStock:results.filter(x=>x.unknownStock).length,conflicts:results.filter(x=>x.conflict).length},readyForSupplier:false};\n}\nexport function validateState(s,data){\n if(!s||typeof s!=='object'||Array.isArray(s))throw Error('Некорректное состояние');\n const ids=new Set(data.rows.map(r=>r.id));\n for(const k of ['rules','orders'])if(!Array.isArray(s[k])||s[k].length>500)throw Error('Слишком много правил или поставок');\n if(!s.edits||typeof s.edits!=='object'||Object.keys(s.edits).length>2000)throw Error('Некорректные правки');\n for(const [id,e]of Object.entries(s.edits)){if(!ids.has(id))throw Error('Неизвестный товар в правках');if(e.qty!==undefined&&e.qty!==null&&e.qty!==''&&(!Number.isInteger(Number(e.qty))||Number(e.qty)<0||Number(e.qty)>100000))throw Error('Количество должно быть целым и неотрицательным');if(!Number.isFinite(Number(e.excludeSales||0))||Number(e.excludeSales||0)<0||Number(e.excludeSales||0)>Number(data.rows.find(r=>r.id===id).sales28||0))throw Error('Исключение из продаж не может быть больше продаж');if(String(e.reason||'').length>4000)throw Error('Комментарий слишком длинный');}\n const orderIds=new Set();\n for(const p of s.orders){if(!p.number||orderIds.has(p.brand+':'+p.number))throw Error('Номер закупки должен быть уникальным внутри бренда');orderIds.add(p.brand+':'+p.number);if(!['notd','biblioteka'].includes(p.brand)||!Array.isArray(p.lines)||p.lines.length>3000)throw Error('Некорректная закупка');if(p.eta&&!/^\\d{4}-\\d{2}-\\d{2}$/.test(p.eta))throw Error('Некорректная дата приезда');const seen=new Set();for(const l of p.lines){if(!ids.has(l.id)||!l.id.startsWith(p.brand+':')||seen.has(l.id))throw Error('Неизвестный или повторный товар в закупке');seen.add(l.id);if(![l.ordered,l.received,l.cancelled].every(x=>Number.isInteger(x)&&x>=0&&x<=100000)||l.received+l.cancelled>l.ordered)throw Error('Проверьте заказано/получено/отменено');}}\n const scopes=new Set(['all','notd','biblioteka',...ids,...data.rows.map(r=>'category:'+r.brand+':'+r.category)]);\n for(const r of s.rules){if(!scopes.has(r.scope)||!['demand','delivery','extra'].includes(r.kind)||!Number.isFinite(Number(r.value))||Number(r.value)<0||Number(r.value)>(r.kind==='demand'?10:r.kind==='delivery'?90:100000))throw Error('Некорректное правило');if(!r.reason?.trim())throw Error('Укажите причину правила');if([r.from,r.to].some(x=>x&&(!/^\\d{4}-\\d{2}-\\d{2}$/.test(x)||!Number.isFinite(dayNumber(x)))))throw Error('Проверьте даты правила');if(r.kind==='extra'&&(!r.incremental||!r.from||!ids.has(r.scope)))throw Error('Разовый заказ: конкретный товар, дата и подтверждение отсутствия резерва');if(r.from&&r.to&&r.to<r.from)throw Error('Дата окончания раньше начала');}\n calculate(data,s);return s;\n}\n","type":"text/javascript;charset=utf-8"},"/assets/parser.js":{"body":"export function columnName(n){let s='';for(n++;n;n=Math.floor((n-1)/26))s=String.fromCharCode(65+(n-1)%26)+s;return s;}\nfunction col(s){return [...s].reduce((n,c)=>n*26+c.charCodeAt(0)-64,0)-1;}\nfunction xml(s){const d=new DOMParser().parseFromString(s,'application/xml');if(d.querySelector('parsererror'))throw Error('Не удалось прочитать XML таблицы');return d;}\nexport function parseCSV(text){const delimiter=text.split(/\\r?\\n/).slice(0,5).join('').includes(';')?';':text.includes('\\t')?'\\t':',';const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='\"'){if(quoted&&text[i+1]==='\"'){cell+='\"';i++;}else quoted=!quoted;}else if(c===delimiter&&!quoted){row.push(cell);cell='';}else if(c==='\\n'&&!quoted){row.push(cell.replace(/\\r$/,''));rows.push(row);row=[];cell='';}else cell+=c;}if(cell||row.length){row.push(cell.replace(/\\r$/,''));rows.push(row);}return rows.map((cells,i)=>({number:i+1,cells}));}\nexport async function parseFile(file){\n if(file.size>3.5*1024*1024)throw Error('Максимум 3,5 МБ на файл. Большой скан сохраните в Drive и загрузите таблицу заказа.');\n const bytes=await file.arrayBuffer(),ext=file.name.split('.').pop().toLowerCase();\n if(ext==='csv')return [{name:'CSV',rows:parseCSV(new TextDecoder().decode(bytes))}];\n if(ext==='xlsx'){\n  // Bound ZIP expansion before decompression, using the standard central directory sizes.\n  const v=new DataView(bytes);let expanded=0,entries=0;for(let i=0;i<bytes.byteLength-46;i++){if(v.getUint32(i,true)===0x02014b50){expanded+=v.getUint32(i+24,true);entries++;i+=45+v.getUint16(i+28,true)+v.getUint16(i+30,true)+v.getUint16(i+32,true);}}if(entries>1500||expanded>50*1024*1024)throw Error('Таблица слишком большая после распаковки');\n  const zip=await window.JSZip.loadAsync(bytes);const read=async p=>{if(!zip.file(p))throw Error('Нет части XLSX: '+p);return xml(await zip.file(p).async('string'));};\n  const ss=zip.file('xl/sharedStrings.xml')?[...(await read('xl/sharedStrings.xml')).getElementsByTagName('si')].map(x=>x.textContent):[];\n  const rel=[...(await read('xl/_rels/workbook.xml.rels')).getElementsByTagName('Relationship')];const paths=Object.fromEntries(rel.map(x=>[x.getAttribute('Id'),x.getAttribute('Target')]));\n  const sheets=[...(await read('xl/workbook.xml')).getElementsByTagName('sheet')];if(sheets.length>50)throw Error('Слишком много листов');\n  const out=[];for(const sheet of sheets){let target=paths[sheet.getAttribute('r:id')];if(!target)continue;target=target.startsWith('/')?target.slice(1):'xl/'+target;const d=await read(target),rows=[];for(const r of [...d.getElementsByTagName('row')]){const cells=[];if(Number(r.getAttribute('r'))>20000)throw Error('Больше 20 000 строк');for(const c of [...r.getElementsByTagName('c')]){const address=c.getAttribute('r')||'',idx=col(address.match(/[A-Z]+/)?.[0]||'A');if(idx>200)continue;const type=c.getAttribute('t'),value=c.getElementsByTagName('v')[0]?.textContent;cells[idx]=type==='s'?(ss[Number(value)]||''):type==='inlineStr'?(c.getElementsByTagName('is')[0]?.textContent||''):(value??'');}rows.push({number:Number(r.getAttribute('r')),cells});}out.push({name:sheet.getAttribute('name'),rows});}return out;\n }\n if(ext==='pdf'){\n  const pdfjs=await import('/notd-v2-assets/pdf.mjs');pdfjs.GlobalWorkerOptions.workerSrc='/notd-v2-assets/pdf.worker.mjs';\n  const doc=await pdfjs.getDocument({data:bytes,isEvalSupported:false,useSystemFonts:true}).promise;if(doc.numPages>100)throw Error('В PDF больше 100 страниц');const sheets=[];\n  for(let n=1;n<=doc.numPages;n++){const page=await doc.getPage(n),text=await page.getTextContent(),groups=[];for(const item of text.items){if(!item.str?.trim())continue;const y=item.transform[5];let g=groups.find(x=>Math.abs(x.y-y)<3);if(!g){g={y,items:[]};groups.push(g);}g.items.push(item);}const rows=groups.sort((a,b)=>b.y-a.y).map((g,i)=>({number:i+1,cells:g.items.sort((a,b)=>a.transform[4]-b.transform[4]).map(x=>x.str.trim()),page:n}));sheets.push({name:'Страница '+n,rows,pdf:true});}await doc.destroy();if(!sheets.some(x=>x.rows.length))throw Error('Это скан PDF: текста нет. Оригинал сохранён; для расчёта нужен XLSX/CSV или ручной разбор.');return sheets;\n }\n throw Error('Поддерживаются XLSX, CSV и текстовый PDF. Старый XLS пересохраните в XLSX.');\n}\nexport function matchRows(sheet,qtyColumn,headerRow,brand,data){\n const rows=data.rows.filter(r=>r.brand===brand),skuIndex=new Map(),eanIndex=new Map();\n const add=(m,k,id)=>{if(k){const a=m.get(k)||[];a.push(id);m.set(k,a);}};\n for(const r of rows){add(skuIndex,String(r.sku).trim(),r.id);add(eanIndex,String(r.ean||'').trim(),r.id);}\n const result=[];\n for(const r of sheet.rows){if(r.number<=headerRow)continue;const raw=String(r.cells[qtyColumn]??'').trim(),qty=Number(raw.replace(/\\s/g,'').replace(',','.'));if(!raw||!Number.isFinite(qty)||qty<=0)continue;\n  const cells=r.cells.map(x=>String(x??'').trim()),skuMatches=new Set(),eanMatches=new Set();\n  for(const c of cells){for(const id of skuIndex.get(c)||[])skuMatches.add(id);for(const id of eanIndex.get(c)||[])eanMatches.add(id);}\n  // Prefer an unambiguous exact SKU; a shared EAN is never sufficient to choose a shade.\n  const matches=skuMatches.size?skuMatches:eanMatches;\n  result.push({row:r.number,page:r.page,label:cells.filter(Boolean).join(' | ').slice(0,500),qty,id:matches.size===1?[...matches][0]:null,candidates:[...matches],invalid:!Number.isInteger(qty),excluded:false,reason:''});\n }\n return result;\n}\n","type":"text/javascript;charset=utf-8"}};
